"""Separately labelled discovery golden, generated by the real HTTP producer."""
import json
import os
from pathlib import Path

from tests import test_managed_setup_discovery as producer

installed = producer.installed
served_setup = producer.served_setup
GOLDEN = Path(__file__).parent / "fixtures/managed-setup-discovery.json"


async def test_discovery_matches_shared_golden(installed, served_setup, mock):
    body = producer.candidate(installed, mock)
    mock.handlers["profile:list"] = lambda _: {"profiles": [{"id": "default", "name": "Default", "type": "local"},
        {"id": "work", "name": "Work", "type": "local"}], "activeProfileIds": ["default"]}
    result = {}
    for key, selection in [("initial", {}), ("work", {"profile_id": "work"})]:
        request = {**body, **selection}
        status, response = await served_setup("POST", producer.ROUTE, request)
        assert status == 200, response
        record = {"request": request, "response": response}
        if selection:
            preview_request = {"action": "setup.host", "target": {"host": "bat"}, "params": {
                **{k: body[k] for k in ("url", "fingerprint", "secret_ref")}, "profile_id": "work",
                "source_digest": response["source"]["source_digest"], "writes": False, "orchestrate": False,
                "shared_clone_worktrees": False, "managed_roots": []}, "preconditions": {"config_revision": body["revision"]}}
            status, review = await served_setup("POST", "/api/v1/managed/setup/preview", preview_request)
            assert status == 200, review
            record.update(preview_request=preview_request, review=review)
        normalized = json.dumps(record, ensure_ascii=False).replace(body["url"].rstrip("/"), "wss://host-a.example.invalid:9876")
        for actual, example in [(body["fingerprint"], "A" * 64), (body["secret_ref"], "setup_" + "b" * 32),
                (body["revision"], "a" * 64), (response["source"]["source_digest"], "d" * 64)]:
            normalized = normalized.replace(actual, example)
        if selection:
            normalized = normalized.replace(review["preview"]["after_revision"], "b" * 64).replace(review["preview"]["review_digest"], "c" * 64)
        result[key] = json.loads(normalized)
    if os.environ.get("BATC_UPDATE_DISCOVERY_GOLDEN") == "1":
        GOLDEN.write_text(json.dumps(result, ensure_ascii=False, indent=2) + "\n")
    assert result == json.loads(GOLDEN.read_text())
